-- Transactional email outbox (ADR 0010). A global table without row-level security (ADR 0008):
-- the worker reads it without a tenant scope. IDs are UUIDv7 generated by the API.

-- +goose Up
SET LOCAL lock_timeout = '5s';
SET LOCAL statement_timeout = '60s';

CREATE TABLE outbox_emails (
    id              uuid        PRIMARY KEY,
    kind            text        NOT NULL,
    to_email        text        NOT NULL,
    -- Template data, including raw tokens: cleared once sent, and on failed rows once expired.
    payload         jsonb,
    status          text        NOT NULL DEFAULT 'pending',
    -- At most 8 attempts (plus one per crashed lease): integer cannot overflow.
    -- squawk-ignore prefer-bigint-over-int
    attempts        integer     NOT NULL DEFAULT 0,
    next_attempt_at timestamptz NOT NULL DEFAULT now(),
    sent_at         timestamptz,
    last_error      text,
    created_at      timestamptz NOT NULL DEFAULT now(),
    CONSTRAINT outbox_emails_kind_valid CHECK (kind IN ('password_reset', 'password_changed')),
    CONSTRAINT outbox_emails_status_valid CHECK (status IN ('pending', 'sent', 'failed')),
    CONSTRAINT outbox_emails_to_email_length CHECK (char_length(to_email) BETWEEN 3 AND 255),
    CONSTRAINT outbox_emails_attempts_nonnegative CHECK (attempts >= 0),
    CONSTRAINT outbox_emails_last_error_length CHECK (char_length(last_error) <= 1000)
);

-- The worker claims pending rows that are due.
-- The table is created empty in this same migration, so a plain index blocks nobody.
-- squawk-ignore require-concurrent-index-creation
CREATE INDEX outbox_emails_due_idx ON outbox_emails (next_attempt_at) WHERE status = 'pending';

-- +goose Down
-- Down undoes the Up above on a database that has not been used yet; dropping is its purpose.
-- squawk-ignore ban-drop-table
DROP TABLE outbox_emails;
